        private BufferedReader reader;
        private StringTokenizer st;

        public DataReader(BufferedReader reader) {
            this.reader = reader;
        }

        public static DataReader createFromFile(String name) throws FileNotFoundException {
            return new DataReader(new BufferedReader(new FileReader(name)));
        }

        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String s = reader.readLine();
                if (s == null) return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        public String nextToken() throws IOException {
            String token = next();
            if (token == null) throw new NoSuchElementException();
            return token;
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        public int[] readIntArray(int n) throws IOException {
            int[] result = new int[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextInt();
            }
            return result;
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

